<script lang="ts">
 import{onMount}from'svelte';import{workflowApi,type EvidencePolicy}from'../../lib/workflow-api';import type{EvidenceRequirement}from'../../lib/types';import{t}from'../../lib/i18n.svelte';
 let policy=$state<EvidencePolicy|null>(null);let items=$state<EvidenceRequirement[]>([]);let error=$state('');let busy=$state(false);let saved=$state(false);
 onMount(()=>{void workflowApi.policy().then(p=>{policy=p;items=structuredClone(p.proposed?.length?p.proposed:p.requirements)}).catch(e=>error=e.message)});
 async function save(){busy=true;error='';saved=false;try{policy=await workflowApi.savePolicy(items);saved=true}catch(e){error=e instanceof Error?e.message:'Could not save requirements'}finally{busy=false}}
</script>
<details class="disclosure evidence-policy"><summary>{t('Completion evidence requirements')}</summary><p class="secondary-text">{t('Tell customers what documentation this service needs. An operator reviews changes before they apply to future agreements.')}</p><form onsubmit={e=>{e.preventDefault();void save()}}>{#each items as item,i(item.id)}<fieldset disabled={busy}><legend>{t('Requirement {number}',{number:i+1})}</legend><label class="field"><span>{t('Documentation description')}</span><input class="input" bind:value={item.label} required minlength="5" maxlength="200"/></label><label class="field"><span>{t('Documentation type')}</span><select class="input" bind:value={item.kind}><option value="photo">{t('Photo')}</option><option value="document">{t('PDF document')}</option><option value="file">{t('Photo or document')}</option><option value="note">{t('Work note')}</option></select></label><button type="button" class="btn btn-quiet" onclick={()=>items=items.filter(v=>v.id!==item.id)}>{t('Remove requirement')}</button></fieldset>{/each}<div class="row"><button type="button" class="btn btn-quiet" disabled={busy||items.length>=12} onclick={()=>items=[...items,{id:crypto.randomUUID(),label:'',kind:'photo'}]}>{t('Add a requirement')}</button><button class="btn btn-outline" disabled={busy||!items.length}>{t('Send requirements for review')}</button></div></form>{#if saved}<p role="status">{t('Requirements sent for operator review. Existing agreements are unchanged.')}</p>{/if}{#if policy}<p class="meta">{t('Policy status')}: {t(policy.status)}</p>{/if}{#if error}<p class="field-error" role="alert">{t(error)}</p>{/if}</details>
<style>.evidence-policy{display:grid;gap:12px}.evidence-policy form,.evidence-policy fieldset{display:grid;gap:10px}.evidence-policy fieldset{border:0;padding-block:12px;min-width:0}.evidence-policy legend{font-weight:600}</style>
